\label{IntroMV}
  Let $X$ be a locally compact metric space carrying a free, proper, isometric action by a countable discrete group $\Gamma$, and let $Z \subseteq X$ a closed, invariant subspace. There is an algebraic Mayer-Vietoris sequence
  $$
    K_*(C^*(Z)^\Gamma) \to K_*(C^*(X)^\Gamma) \oplus K_*(D^*(Z)^\Gamma) \to K_*(D^*(X,Z)^\Gamma) \xrightarrow{\delta} K_{*-1}(C^*(Z)^\Gamma) \; .
  $$
  Its boundary map fits into the commutative diagram \\
\centerline{
  \xymatrix{
    K^\Gamma_*(X,Z) \ar[r]^\partial \ar[d]_{\mathrm{Ind}_\mathrm{sec}^\Gamma} & K^\Gamma_{*-1}(Z) \ar[d]^{\mathrm{Ind}^\Gamma} \\
    K_*(D^*(X,Z)^\Gamma) \ar[r]_\delta & K_*(C^*(Z)^\Gamma)
  }
}
where $\mathrm{Ind}^\Gamma$ denotes the equivariant coarse index map.

\label{IntroTransform}
  Let $X$ be a locally compact metric space carrying a free, proper, isometric action by a countable discrete group $\Gamma$, and let $Z \subseteq X$ a closed, invariant subspace. There is a commutative diagram \\
  \centerline{\xymatrix{
    K_*^{\Gamma}(Z) \ar[r] \ar[d]_{\mathrm{Ind}^\Gamma} & K^{\Gamma}_*(X) \ar[r] \ar[d]_{\mathrm{Ind}^\Gamma} & K^{\Gamma}_*(X,Z) \ar[r]^\partial \ar[d]_{\mathrm{Ind}^\Gamma_\mathrm{rel}} & K_{*-1}^{\Gamma}(Z) \ar[d]_{\mathrm{Ind}^\Gamma} \\
    K_*\left(C^*(Z)^\Gamma\right) \ar[r] & K_*\left(C^*(X)^\Gamma\right) \ar[r] & K_*\left(C^*(X,Z)^\Gamma\right) \ar[r]_\partial & K_{*-1}\left(C^*(Z)^\Gamma\right)
  }}

The proof is an essentially verbatim adaptation of the proof of \cite[Prop.~4.3.34]{Siegel2012}. The extension by zero of operators over $A$ to operators over $X$ gives rise to the diagram \\
  \centerline{\xymatrix{
    0 \ar[r] & C^*(A)^\Gamma \ar[r] \ar[d] & D^*(A,Z)^\Gamma \ar[r] \ar[d] & \frac{D^*(A,Z)^\Gamma}{C^*(A)^\Gamma} \ar[r] \ar[d] & 0 \\
    0 \ar[r] & C^*(A\subseteq X)^\Gamma \ar[r] & D^*(A\subseteq X,Z)^\Gamma \ar[r] & \frac{D^*(A\subseteq X,Z)^\Gamma}{C^*(A\subseteq X)^\Gamma} \ar[r] & 0
  }}
  Once we show that the first and third vertical arrow are K-theory isomorphisms, the claim will follow from the Five lemma applied to the associated diagram between K-theory long exact sequences. The first vertical arrow is a K-theory isomorphism by \cref{RoeIncl}. To see that third vertical arrow is a K-theory isomorphism as well, note that it fits into the diagram\\
  \centerline{\xymatrix{
    D^*(A,Z)^\Gamma/C^*(A)^\Gamma \ar[r] \ar[d] & \mathfrak{D}(A,Z)^\Gamma/\mathfrak{C}(A)^\Gamma \ar[d] \\
    D^*(A\subseteq X,Z)^\Gamma/C^*(A\subseteq X)^\Gamma \ar[r] & \mathfrak{D}(X,Z)^\Gamma/\mathfrak{C}(X)^\Gamma 
  }}
  The horizontal arrows are isomorphisms by \cref{StructureDual}. The right-vertical arrow is a K-theory isomorphism as well. Indeed, through a combination of \cref{StructureDual} and \cref{EquivQuotient} it suffices to consider the non-equivariant situation. Via \cref{TrivialKtheory} it further suffices that $\mathfrak{D}(A,Z)\hookrightarrow \mathfrak{D}(X,Z)$ induces a K-theory isomorphism, which in turn follows from the fact that both algebras have K-theory naturally isomorphic to $\mathfrak{D}(Z)$ \cite[Lemma~2.2]{Higson1995}. We conclude that $D^*(A,Z)^\Gamma/C^*(A)^\Gamma \to D^*(A\subseteq X,Z)^\Gamma/C^*(A\subseteq X)^\Gamma$ is a K-theory isomorphism as well, finishing the proof.

\label{AlgebraicMV}
There is an algebraic Mayer-Vietoris sequence\\
\centerline{\xymatrix{
K_0\left(C^*(Z)^\Gamma\right) \ar[r] & K_0\left(C^*(X)^\Gamma\right)\oplus K_0\left(D^*(Z)^\Gamma\right) \ar[r] & K_0\left(D^*(X,Z)^\Gamma\right) \ar[d]^\delta \\
K_1\left(D^*(X,Z)^\Gamma\right) \ar[u]^\delta & K_1\left(C^*(X)^\Gamma\right)\oplus K_1\left(D^*(Z)^\Gamma\right) \ar[l] &  K_1\left(C^*(Z)^\Gamma\right) \ar[l]
}}

\label{EquivKhom}
  \begin{itemize}
    \item[(i)] There is a isomorphism
      $$
        K_*^\Gamma(X,Z) \cong K_{*+1}\left( \frac{D^*(X)^\Gamma}{D^*(X,Z)^\Gamma}\right) \; ,
      $$
      which is natural with respect to uniform maps of pairs.
    \item[(ii)] There is an isomorphism
      $$
        K_*^\Gamma(X,Z) \cong K_*(X_\Gamma,Z_\Gamma)
      $$
     which is compatible with boundary maps, i.e. the square \\
      \centerline{\xymatrix{
        K^\Gamma_*(X,Z) \ar[r]^\partial \ar[d]_\sim & K^\Gamma_{*-1}(Z) \ar[d]^\sim \\
        K_*(X_\Gamma) \ar[r]_\partial & K_{*-1}(Z_\Gamma)
      }}
      commutes.
  \end{itemize}

\label{RelIndexNatural}
Let $(X,Z)$ and $(Y,W)$ be pairs of proper locally compact metric spaces with free, proper, isometric $\Gamma$-actions fixing the respective subspace, and let $\Phi: \, (X,Z) \to (Y,W)$ be an equivariant uniform map of pairs. Then, the diagram \\
\centerline{\xymatrix{
K^\Gamma_*(X,Z) \ar[d]_{\mathrm{Ind}_\mathrm{sec}^\Gamma} \ar[r]^{\Phi_*} &  \ar[d]^{\mathrm{Ind}_\mathrm{sec}^\Gamma} K^\Gamma_*(Y,W) \\
K_*(D^*(X,Z)^\Gamma) \ar[r]_{\Phi_*} & K_*(D^*(Y,W)^\Gamma)
}}
commutes.

In the case that $\Gamma$ acts non-cocompactly on $X$, one also sees (relative) equivariant K-homology $K^\Gamma_*(X,Z)$ to be defined as the direct limit of $K_*^\Gamma(Y,Y\cap Z)$, taken over all closed, invariant $Y\subseteq X$ on which $\Gamma$ acts cocompactly. This version can be seen as equivariant K-homology with cocompact supports, whereas the version used in this paper can be seen as equivariant locally finite K-homology. There are natural maps
  $$
    \varinjlim K_*^\Gamma(Y, Y\cap Z) \longrightarrow K_*^\Gamma(X,Z) \; , \; \varinjlim K_*\left(D^*(Y, Y\cap Z)^\Gamma\right) \longrightarrow K_*\left(D^*(X,Z)^\Gamma\right)
  $$
  induced by the inclusions $(Y,Y\cap Z)\hookrightarrow (X,Z)$. As a consequence of \cref{RelIndexNatural}, the diagram \\
  \centerline{\xymatrix{
    \varinjlim K_*^\Gamma(Y, Y\cap Z) \ar[r] \ar[d]_{\varinjlim\mathrm{Ind}_\mathrm{sec}^\Gamma} & K_*^\Gamma(X,Z) \ar[d]^{\mathrm{Ind}_\mathrm{sec}^\Gamma} \\
    \varinjlim K_*\left(D^*(Y, Y\cap Z)^\Gamma\right) \ar[r] &  K_*\left(D^*(X,Z)^\Gamma\right)
  }}
  commutes. Hence, there is an analogous secondary index map on cocompactly supported K-homology, and one may pass frictionlessly from it to its locally finite counterpart.

\label{IndexCommAlgMV}
Let $X$ be a  proper locally compact metric space with free, proper, isometric $\Gamma$-actions, and $Z$ a $\Gamma$-invariant subspace. Then, the diagram \\
\centerline{\xymatrix{
K^\Gamma_{*}(X,Z) \ar[r]^\partial \ar[d]_{\mathrm{Ind}_\mathrm{sec}^\Gamma} & K^\Gamma_{*-1}(Z) \ar[d]^-{\mathrm{Ind}^\Gamma} \\
K_{*}\left( D^*(X,Z)^\Gamma\right) \ar[r]_-\delta & K_{*-1}\left( C^*(Z)^\Gamma \right)
}} 
commutes.

We implicitly use a very ample representation $(H,\sigma)$ such that $(H_Z:=P_ZH, \sigma_Z:=P_Z\sigma(\mathbf{1}_Z\cdot))$ is a very ample representation of $Z$, where $P_Z:=\sigma(\mathbf{1}_Z)$. Then, the upper-corner inclusion of $\mathfrak{D}(Z)^\Gamma \subseteq \mathfrak{B}(H_Z)$ into $\mathfrak{D}(X,Z)^\Gamma \subseteq \mathfrak{B}(H=H_Z\oplus H^\perp_Z)$ realizes the isomorphism $K_*(\mathfrak{D}(Z)^\Gamma)\cong K_*(\mathfrak{D}(X,Z)^\Gamma)$. Restricting the upper corner inclusion gives rise to inclusions $D^*(Z)^\Gamma\hookrightarrow D^*(Z\subseteq X,Z)^\Gamma$ and $C^*(Z)^\Gamma\hookrightarrow C^*(Z\subseteq X)^\Gamma$, with the latter inducing an isomorphism on K-theory by \cref{RoeIncl}. Thus, there is also a well-defined map 
\begin{equation}\label{TauQuot}
\frac{D^*(Z)^\Gamma}{C^*(Z)^\Gamma} \longrightarrow \frac{D^*(Z\subseteq X,Z)^\Gamma}{C^*(Z\subseteq X)^\Gamma} \; .
\end{equation}
For the sake of efficient notation we will denote this and all other maps given or induced by the upper-corner inclusion by $\tau$.

Observe that by \cref{RelQuot} and naturality of the boundary map we have a commutative diagram\\
\centerline{\xymatrix{
K_{*+1}\left( \frac{D^*(X)^\Gamma}{D^{*}(X,Z)^\Gamma} \right) \ar@{=}[r] \ar[d]_{\mathrm{Ind}_\mathrm{sec}^\Gamma} & K_{*+1}\left( \frac{\mathfrak{D}(X)^\Gamma}{\mathfrak{D}(X,Z)^\Gamma} \right) \ar[d]^\partial \\
K_{*}\left( D^*(X,Z)^\Gamma\right) \ar[r] & K_{*}\left( \mathfrak{D}(X,Z)^\Gamma \right)
}}
where the right-vertical arrow represents the boundary map on K-homology. It therefore suffices to prove that that the diagram\\
\begin{equation}\label{DiagramMV}
\xymatrix{
K_{*}\left( D^*(X,Z)^\Gamma\right) \ar[rr] \ar[dr]_{\delta} & & K_{*}\left( \mathfrak{D}(X,Z)^\Gamma \right) \ar[dl]^{\mathrm{Ind}^\Gamma} \\
& K_{*-1}\left(C^*(Z)^\Gamma\right) & }
\end{equation}
commutes. Let us unravel the definitions of $\delta$ and $\mathrm{Ind}^\Gamma$. The former is given by the composition\footnote{This description of the Mayer-Vietoris boundary map can be obtained by viewing the Mayer-Vietoris sequence of a decomposition $A=I+J$ as the long exact sequence of the pair $(I\cap J, I \oplus J)$, where $I\cap J$ is included diagonally in $I\oplus J$.}
\begin{align} \label{DescriptionMVboundary}
K_{*}\left( D^*(X,Z)^\Gamma \right) &\rightarrow K_{*}\left( D^*(X,Z)^\Gamma/C^*(X)^\Gamma\right) \\
&= K_{*}\left( D^*(Z\subseteq X,Z)^\Gamma/C^*(Z\subseteq X)^\Gamma\right) \nonumber \\
& \xrightarrow{\partial} K_{*-1}\left(C^*(Z\subseteq X)^\Gamma\right) \nonumber \\
&\xrightarrow{\sim} K_{*-1}\left( C^*(Z)^\Gamma \right) \; . \nonumber
\end{align}
Here, we used that
\begin{equation}\label{eq_cutoff_Z}
  \frac{D^*(Z\subseteq X,Z)^\Gamma}{C^*(Z\subseteq X)^\Gamma} = \frac{D^*(X,Z)^\Gamma}{C^*(X)^\Gamma} \; ,
\end{equation}
which can be obtained by cutting off near $Z$. The coarse index map $\mathrm{Ind}^\Gamma$ is given by 
\begin{align*}
K_{*}\left( \mathfrak{D}(X,Z)^\Gamma \right) &\xrightarrow{\sim} K_{*}\left( \mathfrak{D}(Z)^\Gamma \right) \\
&\xrightarrow{\sim} K_{*}\left( \mathfrak{D}(Z)^\Gamma/\mathfrak{C}(Z)^\Gamma\right) \\
&= K_{*}\left( D^*(Z)^\Gamma/C^*(Z)^\Gamma\right) \\
& \xrightarrow{\partial} K_{*-1}\left(C^*(Z)^\Gamma\right) \; .
\end{align*}
As discussed above the first arrow is inverse to the upper-corner inclusion. Recall also that the upper-corner inclusion induced the map \eqref{TauQuot} on quotients. Combining this with the definitions of $\delta$ and $\mathrm{Ind}^\Gamma$ we write diagram \eqref{DiagramMV} as 
\begin{equation}\label{DiagramMV2}
\xymatrix{
K_{*}\left( D^*(X,Z)^\Gamma\right) \ar[r] \ar[d] & K_{*}\left( \mathfrak{D}(X,Z)^\Gamma \right) \ar[d]^{\sim} \\
K_{*}\left( \frac{D^*(X,Z)^\Gamma}{C^*(X)^\Gamma}\right) \ar@{=}[d] & \ar[l]_-{\tau_*} K_{*}\left( \frac{D^*(Z)^\Gamma}{C^*(Z)^\Gamma}\right) \ar@{=}[d] \\
K_{*}\left( \frac{D^*(Z\subseteq X,Z)^\Gamma}{C^*(Z\subseteq X)^\Gamma}\right) \ar[d]_\partial & \ar[l]_-{\tau_*} K_{*}\left( \frac{D^*(Z)^\Gamma}{C^*(Z)^\Gamma}\right) \ar[d]^\partial \\
K_{*-1}\left( C^*(Z\subseteq X)^\Gamma \right) & \ar[l]_\sim K_{*-1}\left( C^*(Z)^\Gamma \right) }
\end{equation}
where the bottom horizontal isomorphism is also induced by the upper-corner inclusion. The lower square is commutative by naturality of the boundary map. Therefore it suffices to show commutativity of the upper square. 

To that end, note first that by \cref{StructureDual} the quotient in \eqref{eq_cutoff_Z} is also equal to $\mathfrak{D}(X,Z)^\Gamma/\mathfrak{C}(X)^\Gamma$. The diagram\\
\centerline{\xymatrix{
K_{*}\left( \mathfrak{D}(Z)^\Gamma \right) \ar[r]^-{\tau_*} \ar[d] & K_{*}\left( \mathfrak{D}(X,Z)^\Gamma \right) \ar[d] \\
K_{*}\left( \frac{\mathfrak{D}(Z)^\Gamma}{\mathfrak{C}(Z)^\Gamma}\right)\ar[r]_-{\tau_*} & K_{*}\left( \frac{\mathfrak{D}(X,Z)^\Gamma}{  \mathfrak{C}(X)^\Gamma}\right)
}}
commutes, where we recall that $\tau$ always denotes maps induced by upper-corner inclusion. Recall also that the upper-right isomorphism in \eqref{DiagramMV2} is given by 
$$
K_{*}\left( \mathfrak{D}(X,Z)^\Gamma \right) \xrightarrow{\tau_*^{-1}} K_{*}\left( \mathfrak{D}(Z)^\Gamma \right) \longrightarrow K_{*}\left( \frac{\mathfrak{D}(Z)^\Gamma}{\mathfrak{C}(Z)^\Gamma}\right) = K_{*}\left( \frac{D^*(Z)^\Gamma}{C^*(Z)^\Gamma}\right) \; .
$$
The combination of these facts reduces the upper square in \eqref{DiagramMV2} to the commutativity of \\
\centerline{\xymatrix{
K_{*}\left( D^*(X,Z)^\Gamma\right) \ar[r] \ar[d] & K_{*}\left( \mathfrak{D}(X,Z)^\Gamma \right) \ar[d] \\
 K_{*}\left( \frac{D^*(X,Z)^\Gamma}{C^*(X)^\Gamma}\right) \ar@{=}[r]& K_{*}\left( \frac{\mathfrak{D}(X,Z)^\Gamma}{\mathfrak{C}(X)^\Gamma} \right)
}}
which holds even before passing to K-theory. This concludes the proof.

\label{LEStransform}
  There is a commutative diagram \\
\centerline{\xymatrix{
K_*^{\Gamma}(Z) \ar[r] \ar[d]_{\mathrm{Ind}^\Gamma} & K^{\Gamma}_*(X) \ar[r] \ar[d]_{\mathrm{Ind}^\Gamma} & K^{\Gamma}_*(X,Z) \ar[r]^\partial \ar[d]_{\mathrm{Ind}^\Gamma_\mathrm{rel}} & K_{*-1}^{\Gamma}(Z) \ar[d]_{\mathrm{Ind}^\Gamma} \\
K_*\left(C^*(Z)^\Gamma\right) \ar[r] & K_*\left(C^*(X)^\Gamma\right) \ar[r] & K_*\left(C^*(X,Z)^\Gamma\right) \ar[r]_\partial & K_{*-1}\left(C^*(Z)^\Gamma\right)
}}

Commutativity of the first square is due to the naturality of the (non-relative) index map. Using \cref{EquivKhom} and naturality of the K-theory boundary map, it is not hard to see that the relative index map $\mathrm{Ind}^\Gamma_\mathrm{rel}$ can also be written as the composition
$$
  K_{*+1}\left(\frac{D^*(X)^\Gamma}{D^*(X,Z)^\Gamma}\right) \longrightarrow K_{*+1}\left( \frac{D^*(X)^\Gamma/D^*(X,Z)^\Gamma}{C^*(X,Z)^\Gamma} \right) \xlongrightarrow{\partial} K_*\left( C^*(X,Z)^\Gamma \right) \; ,
$$
where one uses that $C^*(X,Z)^\Gamma$ is included as an ideal in $D^*(X)^\Gamma/D^*(X,Z)^\Gamma$. The second square can thus be written as \\
\centerline{\xymatrix{
K_{*+1}\left(\frac{D^*(X)^\Gamma}{C^*(X)^\Gamma}\right) \ar[r] \ar[dd]_{\partial} & K_{*+1}\left(\frac{D^*(X)^\Gamma}{D^*(X,Z)^\Gamma}\right) \ar[d] \\
& K_{*+1}\left( \frac{D^*(X)^\Gamma/D^*(X,Z)^\Gamma}{C^*(X,Z)^\Gamma} \right) \ar[d]^\partial \\
K_*\left(C^*(X)^\Gamma\right) \ar[r] & K_*\left(C^*(X,Z)^\Gamma\right)
}}
which commutes by naturality of the boundary map. Lastly, inserting the definition of the relative index map, write the third square as \\
\centerline{\xymatrix{
K^{\Gamma}_*(X,Z) \ar[rr]^\partial \ar[d]_{\mathrm{Ind}_\mathrm{sec}^\Gamma} && K_{*-1}^{\Gamma}(Z) \ar[d]^{\mathrm{Ind}^\Gamma} \\
K_*\left(D^*(X,Z)^\Gamma\right) \ar[r]_{\mathscr{F}_*} & K_*\left(C^*(X,Z)^\Gamma\right) \ar[r]_\partial & K_{*-1}\left(C^*(Z)^\Gamma\right)
}}
Comparing with \eqref{DescriptionMVboundary}, one sees the composition 
$$
K_*\left(D^*(X,Z)^\Gamma\right) \xrightarrow{\mathscr{F}_*} K_*\left(C^*(X,Z)^\Gamma\right) \xrightarrow{\partial} K_{*-1}\left(C^*(Z)^\Gamma\right)
$$ 
to coincide with the algebraic Mayer-Vietoris boundary map. Thus, commutativity of the last square is a consequence of \cref{IndexCommAlgMV}.

Consider the image of $[\slashed{D}_{\Omega}] \in K_*(\overline{\Omega},\partial\Omega)$ under the maps of the diagram \\
  \centerline{\xymatrix{
    K_{*}^\Gamma(\overline{\Omega},\partial\Omega) \ar[r]^\partial \ar[d]_{\mathrm{Ind}_\mathrm{sec}^\Gamma} & K_{*-1}^\Gamma(\partial\Omega) \ar[d]^-{\mathrm{Ind}^\Gamma} \\
    K_{*}\left( D^*(\overline{\Omega},\partial\Omega)^\Gamma\right) \ar[r]_-\delta & K_{*-1}\left( C^*(\partial\Omega)^\Gamma \right)
  }} 
  Its image under the upper-horizontal map is $[\slashed{D}_{\partial\Omega}] \in K_{*-1}^\Gamma(\partial\Omega)$ by boundary-of-Dirac-is-Dirac\footnote{Using \cref{EquivKhom}, the equivariant case of boundary-of-Dirac-is-Dirac can be reduced to the non-equivariant case, which is discussed in e.g. \cite[~Prop. 11.2.5]{HigsonRoe2000}.}. Hence, going right then down computes $\mathrm{Ind}^\Gamma(\slashed{D}_{\partial\Omega})$. On the other hand, since we assumed that $\partial\Omega \hookrightarrow \overline{\Omega}$ is a coarse equivalence, the Mayer-Vietoris boundary map $\delta$ is zero, as discussed in \cref{CoarseEqMV}. Thus, going down then right gives zero.

\label{RelIndRho}
Let $\overline{\Omega}$ be an even-dimensional, collared spin manifold carrying a free and proper action of $\Gamma$ by spin isometries.
\begin{itemize}
  \item[(i)] If $\overline{\Omega}$ has uniformly positive scalar curvature, then\footnote{Recall that $\mathrm{Ind}^\Gamma_{\partial\Omega}$ denotes the refinement of the secondary index map defined in \eqref{refined_index}, and that $\slashed{D}_\Omega$ is in its domain, since the upsc-assumption implies $\chi(\slashed{D}_\Omega)$ to be an involution modulo $D^*(\partial\Omega\subseteq\overline{\Omega},\partial\Omega)$ by \cref{InvolutionModBdry}.}
  $$
    \mathrm{Ind}^\Gamma_{\partial\Omega}(\slashed{D}_\Omega) = \rho^\Gamma(\slashed{D}_{\partial\Omega}) \; \in \; K_{0}\left( D^*(\partial\Omega)^\Gamma\right) \; .
  $$
  \item[(ii)] If $\overline{\Omega}$ only has uniformly positive scalar curvature near the boundary, then
  $$
    \mathrm{Ind}_\mathrm{sec}^\Gamma(\slashed{D}_\Omega) = \mathrm{Ind}^\Gamma_{APS}(\slashed{D}_\Omega) + \rho(\slashed{D}_{\partial\Omega}) \; \in \; K_{0}\left( D^*(\overline{\Omega},\partial\Omega)^\Gamma\right) \; .
  $$
\end{itemize}

\label{decomp}
  Assume that $\Sigma$ has uniformly positive scalar curvature.
  \begin{itemize}
      \item[(i)] $\psi_{\overline{\Omega}} \chi(\slashed{D}_M) \psi_{\Sigma_\infty}$ and $\psi_{\Sigma_\infty} \chi(\slashed{D}_M) \psi_{\overline{\Omega}}$ are in $D^*(\Sigma\subseteq M,\Sigma)^\Gamma$.
      \item[(ii)] $\psi_{\overline{\Omega}}\chi(\slashed{D}_M)\psi_{\overline{\Omega}}$ represents $[\slashed{D}_\Omega] \in K^\Gamma_0(\overline{\Omega},\Sigma)$.
      \item[(iii)] $\psi_{\Sigma_\infty}\chi(\slashed{D}_M)\psi_{\Sigma_\infty}$ represents the class of $\slashed{D}_{\Sigma_\infty}$ in $K^\Gamma_0(D^*(\Sigma_\infty)^\Gamma/D^*(\Sigma\subseteq\Sigma_\infty,\Sigma)^\Gamma)$.
      \item[(iv)] If $\overline{\Omega}$ has uniformly positive scalar curvature, then $\psi_{\overline{\Omega}}\chi(\slashed{D}_M)\psi_{\overline{\Omega}}$ represents the class of $\slashed{D}_\Omega$ in $K^\Gamma_0(D^*(\overline{\Omega})^\Gamma/D^*(\Sigma\subseteq\overline{\Omega},\Sigma)^\Gamma)$.
  \end{itemize}
